static void tide_apply_from(tide_world *w, tide_queue_place at)
{
    for (tide_command *c; (c = tide_queue_next(&w->commands, &at));) {
        if (c->depth >= TIDE_MAX_CHAIN) tide_endless_chain(c, "tick");
        w->tide_chain = c->depth + 1u; // What its handlers record is one further down
        switch (c->kind) {
        case TIDE_CMD_SPAWN: tide_apply_spawn(w, c); break;
        case TIDE_CMD_ADD: tide_apply_add(w, c); break;
        case TIDE_CMD_REMOVE: tide_apply_remove(w, c); break;
        case TIDE_CMD_DESTROY: tide_apply_destroy(w, c); break;
        case TIDE_CMD_EVENT: tide_apply_event(w, c); break;
        case TIDE_CMD_UNLOAD: tide_apply_unload(w, c); break;
        case TIDE_CMD_SNAP: tide_entity_snap(&w->entities, c->entity); break;
        default: break;
        }
    }
    w->tide_chain = 0;
}

static void tide_apply_commands(tide_world *w)
{
    tide_apply_from(w, (tide_queue_place){0, 0});
    // Every scene unloaded: Main loads again.
    if (w->arch2_Main.count == 0) {
        const tide_queue_place from = tide_queue_end(&w->commands);
        tide_cmd_load2(w, (tide_spawn2){.Main = (Main){0}});
        tide_apply_from(w, from);
    }
    tide_queue_clear(&w->commands);
}

