void tide_world_copy(tide_world *restrict to, const tide_world *restrict from)
{
    to->Time = from->Time;
    to->Yard = from->Yard;
    tide_entities_copy(&to->entities, &from->entities);
    tide_table_copy(&to->arch0_Body, &from->arch0_Body, &tide_columns_arch0_Body);
    tide_table_copy(&to->arch1_Crate, &from->arch1_Crate, &tide_columns_arch1_Crate);
    tide_table_copy(&to->arch2_Main, &from->arch2_Main, &tide_columns_arch2_Main);
    tide_queue_copy(&to->commands, &from->commands);
}

uint64_t tide_world_hash(const tide_world *w)
{
    uint64_t h = TIDE_HASH_START;
    h = tide_hash_more(h, &w->Time, sizeof w->Time);
    h = tide_hash_more(h, &w->Yard, sizeof w->Yard);
    h = tide_entities_hash(h, &w->entities);
    h = tide_table_hash(h, &w->arch0_Body, &tide_columns_arch0_Body);
    h = tide_table_hash(h, &w->arch1_Crate, &tide_columns_arch1_Crate);
    h = tide_table_hash(h, &w->arch2_Main, &tide_columns_arch2_Main);
    h = tide_queue_hash(h, &w->commands);
    return tide_hash_end(h);
}

void tide_world_free(tide_world *w)
{
    tide_entities_free(&w->entities);
    tide_table_free(&w->arch0_Body, &tide_columns_arch0_Body);
    tide_table_free(&w->arch1_Crate, &tide_columns_arch1_Crate);
    tide_table_free(&w->arch2_Main, &tide_columns_arch2_Main);
    tide_queue_free(&w->commands);
    memset(w, 0, sizeof *w);
}

uint32_t tide_world_pack(const tide_world *w, uint8_t *out, const uint32_t capacity)
{
    uint64_t size = sizeof *w + tide_entities_packed_size(&w->entities);
    size += tide_table_packed_size(&w->arch0_Body, &tide_columns_arch0_Body);
    size += tide_table_packed_size(&w->arch1_Crate, &tide_columns_arch1_Crate);
    size += tide_table_packed_size(&w->arch2_Main, &tide_columns_arch2_Main);
    size += tide_queue_packed_size(&w->commands);
    if (size > UINT32_MAX) tide_out_of_memory();
    if (!out || size > capacity) return (uint32_t)size;
    tide_world *header = malloc(sizeof *header); // Storage pointers are cleared before serialization
    if (!header) tide_out_of_memory();
    memcpy(header, w, sizeof *header);
    memset(&header->entities, 0, sizeof header->entities);
    memset(&header->arch0_Body, 0, sizeof header->arch0_Body);
    memset(&header->arch1_Crate, 0, sizeof header->arch1_Crate);
    memset(&header->arch2_Main, 0, sizeof header->arch2_Main);
    memset(&header->commands, 0, sizeof header->commands);
    tide_writer bytes = {out, capacity, 0, false, false};
    tide_write_bytes(&bytes, header, sizeof *header);
    free(header);
    tide_entities_pack(&w->entities, &bytes);
    tide_table_pack(&w->arch0_Body, &tide_columns_arch0_Body, &bytes);
    tide_table_pack(&w->arch1_Crate, &tide_columns_arch1_Crate, &bytes);
    tide_table_pack(&w->arch2_Main, &tide_columns_arch2_Main, &bytes);
    tide_queue_pack(&w->commands, &bytes);
    return bytes.size;
}

// Each row's entity is alive and there, and as many are there as are alive somewhere
static bool tide_world_placed(const tide_world *w)
{
    bool ok = true;
    uint32_t placed = 0;
    for (uint32_t i = 0; ok && i < w->arch0_Body.count; i++, placed++) {
        const tide_location at = tide_entity_location(&w->entities, *((const tide_entity *)tide_table_get(&w->arch0_Body, &tide_columns_arch0_Body, i, 0)));
        ok = at.archetype == 0u && at.row == i;
    }
    for (uint32_t i = 0; ok && i < w->arch1_Crate.count; i++, placed++) {
        const tide_location at = tide_entity_location(&w->entities, *((const tide_entity *)tide_table_get(&w->arch1_Crate, &tide_columns_arch1_Crate, i, 0)));
        ok = at.archetype == 1u && at.row == i;
    }
    for (uint32_t i = 0; ok && i < w->arch2_Main.count; i++, placed++) {
        const tide_location at = tide_entity_location(&w->entities, *((const tide_entity *)tide_table_get(&w->arch2_Main, &tide_columns_arch2_Main, i, 0)));
        ok = at.archetype == 2u && at.row == i;
    }
    for (uint32_t i = 0; ok && i < w->entities.next_unused; i++) {
        const tide_location at = tide_entity_location(&w->entities, tide_entity_in_slot(&w->entities, i));
        if (at.archetype != TIDE_ARCHETYPE_NONE) ok = placed-- > 0;
    }
    return ok && placed == 0;
}

bool tide_world_unpack(tide_world *w, const uint8_t *data, const uint32_t size)
{
    tide_world_free(w);
    if (size < sizeof *w) return false;
    memcpy(w, data, sizeof *w);
    memset(&w->entities, 0, sizeof w->entities);
    memset(&w->arch0_Body, 0, sizeof w->arch0_Body);
    memset(&w->arch1_Crate, 0, sizeof w->arch1_Crate);
    memset(&w->arch2_Main, 0, sizeof w->arch2_Main);
    memset(&w->commands, 0, sizeof w->commands);
    tide_reader bytes = {data, size, sizeof *w, false};
    bool ok = tide_entities_unpack(&w->entities, &bytes);
    ok = ok && tide_table_unpack(&w->arch0_Body, &tide_columns_arch0_Body, &bytes);
    ok = ok && tide_table_unpack(&w->arch1_Crate, &tide_columns_arch1_Crate, &bytes);
    ok = ok && tide_table_unpack(&w->arch2_Main, &tide_columns_arch2_Main, &bytes);
    ok = ok && tide_queue_unpack(&w->commands, &bytes, tide_command_fits);
    ok = ok && bytes.at == size;
    ok = ok && tide_world_placed(w);
    if (!ok) tide_world_free(w);
    return ok;
}

