typedef struct tide_world_header_data {
    Time Time;
    Yard Yard;
    uint32_t tide_chain;
} tide_world_header_data;

static void tide_world_header(tide_world_header_data *header, const tide_world *w)
{
    memset(header, 0, sizeof *header);
    header->Time = w->Time;
    header->Yard = w->Yard;
    header->tide_chain = w->tide_chain;
}

static void tide_world_take_header(tide_world *w, const tide_world_header_data *header)
{
    w->Time = header->Time;
    w->Yard = header->Yard;
    w->tide_chain = header->tide_chain;
}

static uint8_t *tide_world_pack_for_peer(const tide_world *w, const tide_world *base, const uint8_t *need,
                               const uint32_t need_size, const bool assets, uint32_t *size)
{
    tide_delta_writer d;
    tide_delta_begin(&d, base != NULL, need, need_size, tide_world_hash(w));
    d.assets = assets;
    if (need) base = NULL; // Only the receiver has it
    tide_world_header_data *header = malloc(sizeof *header);
    tide_world_header_data *base_header = base ? malloc(sizeof *base_header) : NULL;
    if (!header || (base && !base_header)) tide_out_of_memory();
    tide_world_header(header, w);
    if (base) tide_world_header(base_header, base);
    tide_delta_region(&d, header, sizeof *header, base ? base_header : NULL, base ? sizeof *base_header : 0u, false,
                      0u);
    free(header);
    free(base_header);
    tide_delta_close(&d);
    tide_entities_pack_delta(&w->entities, base ? &base->entities : NULL, &d);
    tide_table_pack_delta(&w->arch0_Body, base ? &base->arch0_Body : NULL, &tide_columns_arch0_Body, &d);
    tide_table_pack_delta(&w->arch1_Crate, base ? &base->arch1_Crate : NULL, &tide_columns_arch1_Crate, &d);
    tide_table_pack_delta(&w->arch2_Main, base ? &base->arch2_Main : NULL, &tide_columns_arch2_Main, &d);
    tide_queue_pack(&w->commands, &d.bytes);
    return tide_delta_end(&d, size);
}

uint8_t *tide_world_pack_delta(const tide_world *w, const tide_world *base, const uint8_t *need,
                               const uint32_t need_size, uint32_t *size)
{
    return tide_world_pack_for_peer(w, base, need, need_size, false, size);
}

bool tide_world_unpack_delta(tide_world *w, const tide_world *base, const uint8_t *data, const uint32_t size)
{
    tide_world_free(w);
    tide_delta_reader d;
    uint64_t hash;
    bool ok = tide_delta_open(&d, data, size, base != NULL, &hash);
    tide_world_header_data *header = malloc(sizeof *header);
    tide_world_header_data *base_header = base ? malloc(sizeof *base_header) : NULL;
    if (!header || (base && !base_header)) tide_out_of_memory();
    if (base) tide_world_header(base_header, base);
    ok = ok && tide_delta_get(&d, header, sizeof *header, base ? base_header : NULL, base ? sizeof *base_header : 0u);
    ok = ok && tide_delta_closed(&d);
    if (ok) tide_world_take_header(w, header); // Storage is decoded separately
    free(header);
    free(base_header);
    ok = ok && tide_entities_unpack_delta(&w->entities, base ? &base->entities : NULL, &d);
    ok = ok && tide_table_unpack_delta(&w->arch0_Body, base ? &base->arch0_Body : NULL, &tide_columns_arch0_Body, &d);
    ok = ok && tide_table_unpack_delta(&w->arch1_Crate, base ? &base->arch1_Crate : NULL, &tide_columns_arch1_Crate, &d);
    ok = ok && tide_table_unpack_delta(&w->arch2_Main, base ? &base->arch2_Main : NULL, &tide_columns_arch2_Main, &d);
    ok = ok && tide_queue_unpack(&w->commands, &d.bytes, tide_command_fits);
    ok = ok && d.bytes.at == size && tide_world_placed(w) && tide_world_hash(w) == hash;
    if (!ok) tide_world_free(w);
    return ok;
}

uint8_t *tide_world_hash_pages(const tide_world *w, uint32_t *size)
{
    tide_writer out = {.grows = true};
    tide_world_header_data *header = malloc(sizeof *header);
    if (!header) tide_out_of_memory();
    tide_world_header(header, w);
    tide_write_varint(&out, 1);
    tide_write_u64(&out, tide_hash(header, sizeof *header));
    free(header);
    tide_entities_hash_pages(&w->entities, &out);
    tide_table_hash_pages(&w->arch0_Body, &tide_columns_arch0_Body, &out);
    tide_table_hash_pages(&w->arch1_Crate, &tide_columns_arch1_Crate, &out);
    tide_table_hash_pages(&w->arch2_Main, &tide_columns_arch2_Main, &out);
    if (out.overflow) tide_out_of_memory();
    *size = out.size;
    return out.data;
}

uint32_t tide_world_need_pages(const tide_world *base, const uint8_t *hashes, const uint32_t size, uint8_t *out,
                               const uint32_t capacity)
{
    tide_needs n;
    tide_needs_begin(&n, hashes, size, out, capacity);
    tide_world_header_data *header = malloc(sizeof *header);
    if (!header) tide_out_of_memory();
    tide_world_header(header, base);
    tide_needs_one(&n, header, sizeof *header);
    free(header);
    tide_entities_need_pages(&base->entities, &n);
    tide_table_need_pages(&base->arch0_Body, &tide_columns_arch0_Body, &n);
    tide_table_need_pages(&base->arch1_Crate, &tide_columns_arch1_Crate, &n);
    tide_table_need_pages(&base->arch2_Main, &tide_columns_arch2_Main, &n);
    return tide_needs_end(&n);
}

bool tide_local_take_request(tide_local *local, tide_session_request *request, tide_start *start)
{
    if (local->tide_request.kind != TIDE_REQUEST_NONE) {
        *request = local->tide_request;
        *start = local->tide_request_start;
        local->tide_request = (tide_session_request){0};
        local->tide_request_start = (tide_start){0};
        return true;
    }
    if (local->tide_request_open.kind != TIDE_REQUEST_NONE) {
        *request = local->tide_request_open;
        local->tide_request_open = (tide_session_request){0};
        return true;
    }
    if (local->tide_request_watch.kind != TIDE_REQUEST_NONE) {
        *request = local->tide_request_watch;
        local->tide_request_watch = (tide_session_request){0};
        return true;
    }
    if (local->tide_kick_count == 0) {
        if (local->tide_copy.kind == TIDE_REQUEST_NONE) return false;
        *request = local->tide_copy;
        local->tide_copy = (tide_session_request){0};
        return true;
    }
    *request = local->tide_kicks[0];
    local->tide_kick_count--;
    memmove(local->tide_kicks, local->tide_kicks + 1, local->tide_kick_count * sizeof local->tide_kicks[0]);
    memset(&local->tide_kicks[local->tide_kick_count], 0, sizeof local->tide_kicks[0]);
    return true;
}

void tide_local_set_session(tide_local *local, uint32_t state, tide_player_id player, uint32_t ping, bool server,
                            bool open, const char *room)
{
    local->Session.state = (int32_t)state;
    local->Session.player = player;
    local->Session.ping = (int32_t)ping;
    local->Session.server = server;
    local->Session.open = open;
    size_t n = room ? strlen(room) : 0u;
    if (n >= sizeof local->tide_room) n = sizeof local->tide_room - 1u;
    memcpy(local->tide_room, room ? room : "", n);
    memset(local->tide_room + n, 0, sizeof local->tide_room - n);
    tide_local_set_invite(local, local->tide_room);
}

void tide_local_set_invite(tide_local *local, const char *invite)
{
    size_t n = 0u;
    while (invite && n < sizeof local->tide_invite && (unsigned char)invite[n] >= 0x20u
           && (unsigned char)invite[n] <= 0x7Eu) n++;
    if (!invite || n == sizeof local->tide_invite || invite[n]) n = 0u;
    memmove(local->tide_invite, n ? invite : "", n);
    memset(local->tide_invite + n, 0, sizeof local->tide_invite - n);
}

void tide_local_connected(tide_local *local)
{
    tide_cmd_send_Connected(local, (tide_entity){0}, (Connected){0});
}

void tide_local_disconnected(tide_local *local, uint32_t reason, const char *message)
{
    size_t n = message ? strlen(message) : 0u;
    if (n >= sizeof local->tide_message) n = sizeof local->tide_message - 1u;
    memcpy(local->tide_message, message ? message : "", n);
    memset(local->tide_message + n, 0, sizeof local->tide_message - n);
    tide_cmd_send_Disconnected(local, (tide_entity){0}, (Disconnected){.reason = (int32_t)reason});
}

// The game, as sessions run it

static void tide_game_start(void *w, float dt, const void *start, uint32_t seed)
{
    (void)seed;
    tide_world_start(w, dt, start);
}

static void tide_game_tick(void *w, const tide_jobs *jobs)
{
    tide_world_tick_on(w, jobs);
}

static void tide_game_copy(void *to, const void *from)
{
    tide_world_copy(to, from);
}

static uint64_t tide_game_hash(const void *w)
{
    return tide_world_hash(w);
}

static uint64_t tide_game_hash_on(const void *world, const tide_jobs *jobs)
{
    const tide_world *w = world;
    tide_stale_pages stale = {0};
    tide_entities_stale(&w->entities, &stale);
    tide_table_stale(&w->arch0_Body, &tide_columns_arch0_Body, &stale);
    tide_table_stale(&w->arch1_Crate, &tide_columns_arch1_Crate, &stale);
    tide_table_stale(&w->arch2_Main, &tide_columns_arch2_Main, &stale);
    tide_pages_hash(&stale, jobs);
    return tide_world_hash(w);
}

static void tide_game_free(void *w)
{
    tide_world_free(w);
}

static uint32_t tide_game_pack(const void *w, uint8_t *out, uint32_t capacity)
{
    return tide_world_pack(w, out, capacity);
}

static bool tide_game_unpack(void *w, const uint8_t *data, uint32_t size)
{
    return tide_world_unpack(w, data, size);
}

static uint8_t *tide_game_pack_delta(const void *w, const void *base, const uint8_t *need, uint32_t need_size,
                                     bool assets, uint32_t *size)
{
    return tide_world_pack_for_peer(w, base, need, need_size, assets, size);
}

static bool tide_game_unpack_delta(void *w, const void *base, const uint8_t *data, uint32_t size)
{
    return tide_world_unpack_delta(w, base, data, size);
}

static uint8_t *tide_game_hash_pages(const void *w, uint32_t *size)
{
    return tide_world_hash_pages(w, size);
}

static uint32_t tide_game_need_pages(const void *base, const uint8_t *hashes, uint32_t size, uint8_t *out,
                                     uint32_t capacity)
{
    return tide_world_need_pages(base, hashes, size, out, capacity);
}

static bool tide_game_ended(const void *w)
{
    return tide_world_ended(w);
}

static void tide_game_joined(void *w, tide_player_id player)
{
    tide_world_player_joined(w, player);
}

static void tide_game_left(void *w, tide_player_id player)
{
    tide_world_player_left(w, player);
}

