void tide_local_rebind_resources(tide_local *l, const bool same_memory)
{
    (void)l;
    (void)same_memory;
    tide_workers_free(l->tide_workers);
    l->tide_workers = NULL;
    l->tide_worker_jobs = NULL;
    if (!same_memory) tide_render_targets_recreated();
}

